<script setup>
import { onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { http, unwrap } from '../services/http.js'
const q=useQuasar(),catalog=ref({}),scopes=ref([]),password=ref(''),file=ref(null),busy=ref(false),review=ref(null),selected=ref([]),mode=ref('preserve'),confirmation=ref(''),error=ref(''),result=ref(null),recovery=ref(null),databaseProfile=ref(null)
onMounted(async()=>{try{catalog.value=unwrap(await http.get('/configuration-backup/catalog'));scopes.value=Object.keys(catalog.value);recovery.value=unwrap(await http.get('/configuration-backup/recovery'))?.[0]}catch(e){error.value=e.response?.data?.error?.message||e.message}})
async function showDatabase(){try{databaseProfile.value=JSON.stringify(unwrap(await http.get('/configuration-backup/database-profile')),null,2)}catch(e){error.value=e.message}}
async function undo(){q.dialog({title:'Desfazer importação',message:'Digite DESFAZER IMPORTAÇÃO. Alterações posteriores impedem a recuperação automática.',prompt:{model:''},cancel:true,persistent:true}).onOk(async confirmation=>{try{await http.post('/configuration-backup/undo',{id:result.value?.journalId||recovery.value?._id,confirmation});result.value=null;recovery.value=null;q.notify({type:'positive',message:'Configurações anteriores recuperadas.'})}catch(e){error.value=e.response?.data?.error?.message||e.message}})}
async function run(action){busy.value=true;error.value='';try{if(action==='export'){const response=await http.post('/configuration-backup/export',{scopes:scopes.value,password:password.value},{responseType:'blob',timeout:180000});const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download='notifyflow-configuracoes.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);password.value=''}else if(action==='review'){const data=new FormData();data.append('file',file.value);data.append('password',password.value);review.value=unwrap(await http.post('/configuration-backup/review',data,{timeout:180000}));selected.value=review.value.items.map(row=>row.index);password.value='';result.value=null}else{result.value=unwrap(await http.post('/configuration-backup/apply',{id:review.value.id,indices:selected.value,mode:mode.value,confirmation:confirmation.value},{timeout:180000}));review.value=null;confirmation.value='';q.notify({type:'positive',message:'Importação concluída. Atualize as telas para usar as configurações.'})}}catch(e){error.value=e.response?.data?.error?.message||e.response?.data?.message||e.message}finally{busy.value=false}}
</script>
<template><q-card flat bordered class="portable-config q-mb-lg"><q-expansion-item icon="import_export" label="Configurações portáteis · Desktop e Cloud" caption="ZIP protegido por senha, com seleção e revisão"><q-card-section><p>Transfira marca, canais, tokens, contatos e configurações entre instalações. Apenas administradores podem usar este recurso. Guarde o ZIP e sua senha separadamente.</p><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><q-banner v-if="result" class="bg-green-1 q-mb-md">{{result.imported}} registro(s) importado(s), {{result.skipped}} preservado(s). Fluxos ficam inativos e programações pausadas. Reinicie o serviço depois de revisar as integrações.<q-btn flat no-caps label="Desfazer esta importação" @click="undo"/></q-banner>
<q-btn v-if="recovery && !result" flat no-caps icon="restore" label="Recuperar configuração anterior à última importação" @click="undo"/>
<template v-if="!review"><div class="scope-grid"><q-checkbox v-for="(label,key) in catalog" :key="key" v-model="scopes" :val="key" :label="label" :disable="busy"/></div><q-input v-model="password" outlined type="password" autocomplete="new-password" label="Senha do ZIP · mínimo 12 caracteres" maxlength="256" :disable="busy" class="q-my-md"/><div class="row q-gutter-md"><q-btn color="primary" no-caps icon="download" label="Exportar categorias selecionadas" :loading="busy" :disable="!scopes.length||password.length<12" @click="run('export')"/><q-file v-model="file" outlined dense accept=".zip" label="Escolher ZIP para revisar" :disable="busy"/><q-btn outline color="primary" no-caps icon="preview" label="Revisar importação" :disable="!file||password.length<12" :loading="busy" @click="run('review')"/></div></template>
<template v-else><q-banner class="bg-amber-1 q-mb-md"><ul><li v-for="note in review.notes" :key="note">{{note}}</li></ul></q-banner><q-select v-model="mode" outlined emit-value map-options label="Registros que já existem" :options="[{label:'Mesclar: preservar os existentes',value:'preserve'},{label:'Substituir os registros selecionados que coincidirem',value:'overwrite'}]" :disable="busy"/><p class="text-caption">Nada fora da seleção será apagado. Desmarque os registros que não deseja importar. Credenciais não são exibidas nesta revisão.</p><div class="row q-gutter-sm"><q-btn flat no-caps label="Selecionar tudo" @click="selected=review.items.map(r=>r.index)"/><q-btn flat no-caps label="Desmarcar tudo" @click="selected=[]"/></div><div class="import-list"><q-checkbox v-for="row in review.items" :key="row.index" v-model="selected" :val="row.index" :disable="busy" :label="`${catalog[row.scope]} · ${row.label} · ${row.conflict?'já existe':'novo'}`"/></div><q-input v-model="confirmation" outlined label="Digite IMPORTAR CONFIGURAÇÕES" :disable="busy" class="q-my-md"/><q-btn color="primary" no-caps label="Confirmar importação revisada" :loading="busy" :disable="!selected.length||confirmation!=='IMPORTAR CONFIGURAÇÕES'" @click="run('apply')"/><q-btn flat no-caps label="Cancelar revisão" :disable="busy" @click="review=null"/></template>
<q-expansion-item icon="storage" label="Perfil de banco importado · sensível"><q-btn flat no-caps label="Exibir perfil protegido" @click="showDatabase"/><q-input v-if="databaseProfile" :model-value="databaseProfile" type="textarea" outlined readonly label="Conexões recuperadas · aplicar pela infraestrutura e reiniciar"/></q-expansion-item><p class="text-caption q-mt-lg">Este pacote não transfere contas administrativas, sessões QR, licenças, filas ou histórico de mensagens. Banco: as URLs são guardadas em um perfil protegido; a aplicação à infraestrutura exige revisão e reinício. Faça o backup completo da instalação para migrações integrais.</p></q-card-section></q-expansion-item></q-card></template>
<style scoped>.portable-config{border-radius:18px}.scope-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}.import-list{display:flex;flex-direction:column;max-height:360px;overflow:auto;border:1px solid #dce8e3;border-radius:12px;padding:12px}.portable-config p{line-height:1.7}</style>
